// validate checks YAML fields that have constraints (negative values rejected
// for durations and byte counts, matching Load()'s behaviour).
func (yc YAMLConfig) validate() error {
	if yc.ReadTimeout != "" {
		if d, err := time.ParseDuration(yc.ReadTimeout); err == nil && d < 0 {
			return fmt.Errorf("config: server_read_timeout must not be negative, got %s", d)
		}
	}
	if yc.WriteTimeout != "" {
		if d, err := time.ParseDuration(yc.WriteTimeout); err == nil && d < 0 {
			return fmt.Errorf("config: server_write_timeout must not be negative, got %s", d)
		}
	}
	if yc.IdleTimeout != "" {
		if d, err := time.ParseDuration(yc.IdleTimeout); err == nil && d < 0 {
			return fmt.Errorf("config: server_idle_timeout must not be negative, got %s", d)
		}
	}
	if yc.MaxHeaderBytes < 0 {
		return fmt.Errorf("config: server_max_header_bytes must not be negative, got %d", yc.MaxHeaderBytes)
	}
	if yc.ShutdownTimeout != "" {
		if d, err := time.ParseDuration(yc.ShutdownTimeout); err == nil && d < 0 {
			return fmt.Errorf("config: shutdown_timeout must not be negative, got %s", d)
		}
	}
	return nil
}

// parseBoolEnvStr is like parseBoolEnv but takes the raw string directly.
func parseBoolEnvStr(v string, def bool) bool {
	switch strings.ToLower(strings.TrimSpace(v)) {
	case "true", "1", "yes", "on":
		return true
	case "false", "0", "no", "off":
		return false
	default:
		return def
	}
}

// Package diag runs boot-time diagnostic checks for the Nexus Proxy
// (issue #32). The diagnostic surfaces the same signals the chat
// handler's hot path depends on — Ollama reachability, model
// availability, frontier key validity, VRAM probe budget, RAG
// directory state, on-disk path writability — so a new operator can
// verify their configuration with `nexus check` instead of waiting
// for the first proxied request to 401 or time out.
//
// The package is stdlib-only: every check uses net/http + os.Stat +
// probe.NewOllamaProbe, all of which are already on the proxy's
// dependency list. No new modules are introduced.
//
// Run takes a config.Config and returns a Result (slice of Check).
// Each Check carries a Name, a Status (pass/fail/warn/skip) and a
// human-readable Detail line. Run always returns every check — the
// caller decides how to render or whether to gate an exit code on
// the failed subset. This mirrors the way `internal/health` reports
// breaker state: collect everything, surface it all at once, let the
// operator decide.
package diag

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
